// New listings in the shape workflow 03 produces. Synthetic. send is false: nothing is posted.
const FIXTURE = {"new": [{"company": "ExampleCo Ashby", "source": "ashby", "source_id": "a-2002", "title": "Strategic Account Manager", "url": "https://jobs.example.test/a/2002", "location_text": "New York, NY", "department": "Sales", "date_posted": "2026-10-04", "matched": {"topic_text": ["university", "education"], "connector": {"title": ["account manager", "strategic account"], "institution": ["university", "higher education"]}, "kept_because": "account or partnership role whose body names higher education"}, "text_sha": "7c7a0c847cffb305"}], "watched": ["ExampleCo Ashby", "ExampleCo Labs", "ExampleCo Recruiters"], "first_time_companies": ["ExampleCo Ashby"], "already": ["ashby:a-2002"], "send": false};
return [{json: FIXTURE}];

// Port of lectern/notify.py: matched_words(), order(), build_messages() and the refusal rule in post().
// Pure functions: no n8n globals. Nothing here can send anything; the Discord node does that, behind a switch.
const PRIORITY = ['Anthropic', 'OpenAI', 'Microsoft', 'Google', 'Figma', 'Canva', 'GitHub', 'Notion'];
const MAX_CHUNK = 1300;
const FOOTER = 'Every row links to the live posting. A person decides; the machine only ranks words.';
const REFUSE = /\/Users\/|\/home\/\w+|[\w.+-]+@[\w-]+\.[\w.]+|discord(app)?\.com\/api\/webhooks/;

function matchedWords(m) {
  if (!m || typeof m !== 'object' || Array.isArray(m)) return '';
  const words = [];
  for (const v0 of Object.values(m)) {
    let v = v0;
    if (v && typeof v === 'object' && !Array.isArray(v)) v = Object.values(v).filter(Array.isArray).flat();
    if (Array.isArray(v)) for (const w of v) if (!words.includes(w)) words.push(w);
  }
  return words.slice(0, 4).join(', ');
}
function order(rows) {
  const rank = {}; PRIORITY.forEach((c, i) => { rank[c] = i; });
  const r = c => (c in rank ? rank[c] : 99);
  const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
  return rows.slice().sort((a, b) => (r(a.company) - r(b.company)) || cmp(a.company, b.company) || cmp(a.title || '', b.title || ''));
}
// Returns {rows, messages}. Drops unwatched companies and rows already posted.
function buildMessages(nw, watched, firstTime, already) {
  const W = new Set(watched), F = new Set(firstTime || []), A = new Set(already || []);
  let rows = nw.filter(r => W.has(r.company) && !A.has(`${r.source}:${r.source_id}`));
  rows = order(rows);
  if (!rows.length) return {rows: [], messages: []};
  const lines = rows.map(r => {
    const loc = (r.location_text || '').split(' | ')[0].split(';')[0].slice(0, 40);
    const tag = F.has(r.company) ? ' (newly watched)' : '';
    const mw = matchedWords(r.matched);
    return `**${r.company}**${tag}: ${(r.title || '').slice(0, 100)}` + (loc ? ` · ${loc}` : '') + (mw ? ` (${mw})` : '') + ` ${r.url || ''}`;
  });
  const msgs = []; let chunk = [], size = 0;
  for (const ln of lines) {
    if (size + ln.length > MAX_CHUNK && chunk.length) { msgs.push(chunk.join('\n')); chunk = []; size = 0; }
    chunk.push(ln); size += ln.length + 1;
  }
  if (chunk.length) msgs.push(chunk.join('\n'));
  msgs[msgs.length - 1] += '\n\n' + FOOTER;
  return {rows, messages: msgs};
}
const refused = text => REFUSE.test(text);
// (node export removed in the n8n copy) module.exports = {buildMessages, matchedWords, order, refused, PRIORITY, MAX_CHUNK, FOOTER};

const i = $input.first().json;
const label = i.label || ('run ' + (i.date || ''));
const {rows, messages} = buildMessages(i.new || [], i.watched || [], i.first_time_companies || [], i.already || []);
const title = `Jobs: ${rows.length} new possible listings (${label})`;
if (!messages.length) return [{json: {nothing_new: true, rows: [], messages: [], send: false}}];
return messages.map((m, n) => {
  const head = messages.length > 1 ? `${title} (${n + 1}/${messages.length})` : title;
  const content = `**${head}**\n${m}`;
  const bad = refused(content);
  return {json: {nothing_new: false, rows: n === 0 ? rows.map(r => `${r.source}:${r.source_id}`) : [], message: m, content, refused: bad, send: Boolean(i.send) && !bad}};
});

const built = $('Build messages').all().map(i => i.json);
if (built.length === 1 && built[0].nothing_new) return [{json: {rows: [], messages: [], sent_count: 0, posted_ids: [], refused: 0}}];
const sent = $('Discord').isExecuted ? $('Discord').all().length : 0;
const rows = built.flatMap(b => b.rows);
return [{json: {rows, messages: built.map(b => b.message), sent_count: sent, refused: built.filter(b => b.refused).length,
  posted_ids: sent === built.length ? rows : []}}];   // an id is recorded as posted only if every message went out
